w=Path(__file__).resolve().parent
def replace_par(text,prefix,new):
    ps=text.split('\n')
    idx=[i for i,p in enumerate(ps) if p.startswith(prefix)]
    assert len(idx)==1,prefix
    ps[idx[0]]=new
    return '\n'.join(ps)
